INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-younimo-1', 'sent-ex-younimo-1', 'en', 'Even if I wanted to go, I have no time.', 'authored'),
  ('st-ex-younimo-2', 'sent-ex-younimo-2', 'en', 'Try as I might to sleep, I cannot.', 'authored'),
  ('st-ex-younimo-3', 'sent-ex-younimo-3', 'en', 'Even if I wanted to buy it, I have no money.', 'authored'),
  ('st-ex-younimo-4', 'sent-ex-younimo-4', 'en', 'Even if I wanted to get in touch, there is no telephone.', 'authored'),
  ('st-ex-moshinai-1', 'sent-ex-moshinai-1', 'en', 'He will not so much as apologise.', 'authored'),
  ('st-ex-moshinai-2', 'sent-ex-moshinai-2', 'en', 'He got angry without even listening.', 'authored'),
  ('st-ex-moshinai-3', 'sent-ex-moshinai-3', 'en', 'He will not so much as lend a hand.', 'authored'),
  ('st-ex-moshinai-4', 'sent-ex-moshinai-4', 'en', 'It never even crossed my mind.', 'authored'),
  ('st-ex-tebakariiru-1', 'sent-ex-tebakariiru-1', 'en', 'My little brother does nothing but play.', 'authored'),
  ('st-ex-tebakariiru-2', 'sent-ex-tebakariiru-2', 'en', 'He does nothing but sleep.', 'authored'),
  ('st-ex-tebakariiru-3', 'sent-ex-tebakariiru-3', 'en', 'Stop crying and talk to me.', 'authored'),
  ('st-ex-tebakariiru-4', 'sent-ex-tebakariiru-4', 'en', 'He does nothing but watch television.', 'authored'),
  ('st-ex-tetamaranai-1', 'sent-ex-tetamaranai-1', 'en', 'It is unbearably hot.', 'authored'),
  ('st-ex-tetamaranai-2', 'sent-ex-tetamaranai-2', 'en', 'I want to see her so much I cannot bear it.', 'authored'),
  ('st-ex-tetamaranai-3', 'sent-ex-tetamaranai-3', 'en', 'I am so sleepy I cannot stand it.', 'authored'),
  ('st-ex-tetamaranai-4', 'sent-ex-tetamaranai-4', 'en', 'I am so happy I cannot contain myself.', 'authored'),
  ('st-ex-shikataganai-1', 'sent-ex-shikataganai-1', 'en', 'I am dreadfully cold.', 'authored'),
  ('st-ex-shikataganai-2', 'sent-ex-shikataganai-2', 'en', 'It hurts terribly.', 'authored'),
  ('st-ex-shikataganai-3', 'sent-ex-shikataganai-3', 'en', 'I am dreadfully tired.', 'authored'),
  ('st-ex-shikataganai-4', 'sent-ex-shikataganai-4', 'en', 'I am impossibly busy.', 'authored'),
  ('st-ex-zuniwairarenai-1', 'sent-ex-zuniwairarenai-1', 'en', 'I cannot help laughing.', 'authored'),
  ('st-ex-zuniwairarenai-2', 'sent-ex-zuniwairarenai-2', 'en', 'I could not help crying.', 'authored'),
  ('st-ex-zuniwairarenai-3', 'sent-ex-zuniwairarenai-3', 'en', 'I cannot keep it to myself.', 'authored'),
  ('st-ex-zuniwairarenai-4', 'sent-ex-zuniwairarenai-4', 'en', 'I could not stop myself buying it.', 'authored'),
  ('st-ex-tewanaranai-1', 'sent-ex-tewanaranai-1', 'en', 'A promise must not be forgotten.', 'authored'),
  ('st-ex-tewanaranai-2', 'sent-ex-tewanaranai-2', 'en', 'You must not swim in the river.', 'authored'),
  ('st-ex-tewanaranai-3', 'sent-ex-tewanaranai-3', 'en', 'The rules must not be broken.', 'authored'),
  ('st-ex-tewanaranai-4', 'sent-ex-tewanaranai-4', 'en', 'You must not give up.', 'authored'),
  ('st-ex-niatatte-1', 'sent-ex-niatatte-1', 'en', 'On setting out, there are some things to be careful of.', 'authored'),
  ('st-ex-niatatte-2', 'sent-ex-niatatte-2', 'en', 'On starting, preparation is needed.', 'authored'),
  ('st-ex-niatatte-3', 'sent-ex-niatatte-3', 'en', 'On entering the school, I hand in the paperwork.', 'authored'),
  ('st-ex-niatatte-4', 'sent-ex-niatatte-4', 'en', 'On starting the new job, I talked it over first.', 'authored'),
  ('st-ex-nisaishite-1', 'sent-ex-nisaishite-1', 'en', 'On graduating, I thank my teachers.', 'authored'),
  ('st-ex-nisaishite-2', 'sent-ex-nisaishite-2', 'en', 'On departing, I said my goodbyes.', 'authored'),
  ('st-ex-nisaishite-3', 'sent-ex-nisaishite-3', 'en', 'For the exam, please read the notes.', 'authored'),
  ('st-ex-nisaishite-4', 'sent-ex-nisaishite-4', 'en', 'On using it, please observe the rules.', 'authored'),
  ('st-ex-wohajime-1', 'sent-ex-wohajime-1', 'en', 'The teachers and the students too all gathered.', 'authored'),
  ('st-ex-wohajime-2', 'sent-ex-wohajime-2', 'en', 'It is popular in many countries, Japan among them.', 'authored'),
  ('st-ex-wohajime-3', 'sent-ex-wohajime-3', 'en', 'My parents and the rest of the family cheered me on.', 'authored'),
  ('st-ex-wohajime-4', 'sent-ex-wohajime-4', 'en', 'The company president and many others took part.', 'authored')
